using System;

namespace DrownedBell.Core
{
    /// <summary>
    /// Chapter III, the Sounding Archive (map in ArchiveData.cs, generated by tools/archive_rooms.py).
    /// Receiving Desk lamp, Silt Stacks (Ink Moth), Listening Cells (Tuning Widow, drum key), the optional Map Loft
    /// (second keeper record), Return Chute (counterweight shortcut, echo drum, moth, drum-key door) and the
    /// Recording Choir (the Archivist). Taking the sea-gate order and reaching the east exit ends the chapter.
    /// </summary>
    public static class SoundingArchive
    {
        public static Level Build()
        {
            Level lv = Level.Parse(ArchiveData.Rows, ArchiveData.Rooms);
            lv.Chapter = Chapter.Archive;
            return lv;
        }

        /// <summary>Where the chute lands in Return Chute; Up rides between here and the lamp once the counterweight is struck.</summary>
        public static readonly Vec2 ChuteStop = new Vec2(100.5f, 2f);
        public const int LoftRoom = 3;

        static bool Near(Vec2 feet, Vec2 p) => MathF.Abs(feet.X - p.X) < 1f && MathF.Abs(feet.Y - p.Y) < 1.25f;

        /// <summary>The Archive's stations, run by World each step: records, keys, the order and the chute.</summary>
        internal static void Stations(World w, bool up, ref bool upHeld)
        {
            Vec2 feet = w.Player.Body.Feet;
            if (!w.LedgerFound && w.Level.Record is Vec2 ledger && Near(feet, ledger))
                w.SetArchiveFlag(GameEventType.LedgerFound, ledger);
            if (w.Widow != null && !w.Widow.Alive && !w.DrumKey && Near(feet, w.Widow.Body.Feet))
                w.SetArchiveFlag(GameEventType.DrumKeyTaken, w.Widow.Body.Feet);
            if (w.Archivist != null && !w.Archivist.Alive && !w.OrderTaken && Near(feet, w.Archivist.DropAt))
                w.SetArchiveFlag(GameEventType.OrderTaken, w.Archivist.DropAt);
            if (up && !upHeld && w.GrateOpen)
            {
                Vec2? target = Near(feet, ChuteStop) ? w.Level.Checkpoint : Near(feet, w.Level.Checkpoint) ? ChuteStop : (Vec2?)null;
                if (target.HasValue) w.Ride(target.Value);
            }
            upHeld = up;
        }

        // ---- input-only route, for the headless checks and the standalone QA pilot ----------------------------

        /// <summary>Seconds of input lag the scripted diver is playing with; it reacts that much earlier (see SluiceWorks.Lead).</summary>
        public static float Lead;

        public static readonly Vec2 StackFoot = new Vec2(68.5f, 2f);
        const float LoftFloor = 20f;

        /// <summary>True when a ripple will reach the diver within about a quarter second, or is about to start beside them.</summary>
        internal static bool RippleComing(World w)
        {
            Body b = w.Player.Body;
            bool Close(System.Collections.Generic.List<Shockwave> waves)
            {
                foreach (Shockwave s in waves)
                {
                    if (System.MathF.Abs(s.FloorY - b.Bottom) > 1.5f) continue;
                    // Time until the wave's front edge meets the diver, counting the diver's own run towards it.
                    float gap = (b.Pos.X - s.X) * s.Dir - b.Half.X - 0.4f;
                    float closing = w.BossT.WaveSpeed - b.Vel.X * s.Dir;
                    if (gap > -0.8f && gap < closing * (0.1f + Lead)) return true;
                }
                return false;
            }
            bool Beside(float x, float y) => System.MathF.Abs(b.Pos.X - x) < 3f && System.MathF.Abs(b.Bottom - y) < 1.5f;
            foreach (RippleBell bell in w.RippleBells)
            {
                if (bell.Room != w.Room || bell.Harmless) continue;
                if (Close(bell.Waves)) return true;
                if (Beside(bell.Pos.X, bell.Floor) && (bell.Windup > 0.88f || (bell.EchoIn >= 0f && bell.EchoIn < 0.1f))) return true;
            }
            foreach (Enemy e in w.Foes)
            {
                if (e.Room != w.Room) continue;
                if (e is TuningWidow tw)
                {
                    if (Close(tw.Waves)) return true;
                    bool soon = (tw.Beat == WidowBeat.Spread && tw.Elapsed > TuningWidow.SpreadTime - 0.1f) ||
                                (tw.Beat == WidowBeat.Ring && tw.Elapsed > RippleBell.EchoDelay - 0.1f);
                    if (tw.Alive && soon && Beside(tw.Body.Pos.X, tw.Body.Bottom)) return true;
                }
                if (e is Tidekeeper tk)
                {
                    if (Close(tk.Waves)) return true;
                    bool soonWave = tk.Beat == KeeperBeat.Windup && (tk.Attack == KeeperAttack.Wave || tk.Attack == KeeperAttack.Echo) &&
                                    tk.Elapsed > tk.WindupTime(tk.Attack) - 0.1f;
                    bool soonEcho = tk.EchoIn >= 0f && tk.EchoIn < 0.1f;
                    if (tk.Alive && (soonWave || soonEcho) && Beside(tk.Body.Pos.X, tk.Body.Bottom)) return true;
                }
                if (e is Archivist ar)
                {
                    if (Close(ar.Waves)) return true;
                    if (ar.EchoIn >= 0f && ar.EchoIn < 0.1f && Beside(ar.DropAt.X, ar.DropAt.Y)) return true;
                }
            }
            return false;
        }

        internal static PlayerInput RouteInput(World w, bool takeLedger = true)
        {
            Vec2 feet = w.Player.Body.Feet;
            float target = w.Level.Outlet.Value.X;
            bool down = false, climb = false, attack = feet.X > 64f;

            if (!w.GrateOpen && feet.X < w.Level.Lever.X) target = w.Level.Lever.X - 1.05f;
            if (w.Widow != null && !w.DrumKey && feet.X > 64f)
                target = w.Widow.Alive ? w.Widow.Body.Pos.X - 1.5f : w.Widow.Body.Feet.X;
            bool grounded = w.Player.Body.Grounded;
            if (takeLedger && !w.LedgerFound && feet.X > 64f && feet.X < 96f && (grounded || feet.Y > 2.5f))
            {
                if (feet.Y < LoftFloor - 0.1f) { target = StackFoot.X; climb = System.MathF.Abs(feet.X - StackFoot.X) < 0.4f; }
                else target = w.Level.Record.Value.X;
            }
            else if (grounded && feet.Y > StackFoot.Y + 0.5f && feet.X > 64f && feet.X < 96f)
            {
                // Back down the shelf stack: drop through each shelf to the floor (the top shelves sit under a low ceiling).
                target = StackFoot.X;
                down = System.MathF.Abs(feet.X - StackFoot.X) < 0.4f;
            }

            foreach (Enemy e in w.Foes)
            {
                if (e.Room != w.Room) continue;
                if (e is InkMoth moth && moth.Alive && (moth.Beat == MothBeat.Mark || moth.Beat == MothBeat.Dive) &&
                    System.MathF.Abs(feet.X - moth.Mark.X) < 2.2f && System.MathF.Abs(feet.Y - moth.Mark.Y) < 1.5f)
                    target = moth.Mark.X + (feet.X >= moth.Mark.X ? 3f : -3f);
                if (e is Archivist ar)
                {
                    RoomInfo r = w.Level.Rooms[ar.Room];
                    if (!ar.Alive) { if (!w.OrderTaken) target = ar.DropAt.X; continue; }
                    if (ar.Beat == InkBeat.Mark || ar.Beat == InkBeat.Dive)
                    {
                        // Clear of the real mark by three tiles, on whichever side is nearest and inside the room.
                        float lo = r.MinX + 1.5f, hi = r.MaxX - 1.5f, best = feet.X, bestCost = float.PositiveInfinity;
                        if (System.MathF.Abs(feet.X - ar.RealMark.X) < 2.8f)
                            foreach (float side in new[] { -3.2f, 3.2f })
                            {
                                float cx = ar.RealMark.X + side;
                                if (cx < lo || cx > hi) continue;
                                float cost = System.MathF.Abs(cx - feet.X);
                                if (cost < bestCost) { bestCost = cost; best = cx; }
                            }
                        target = best;
                    }
                    else if (ar.Beat == InkBeat.Recover)
                    {
                        // Punish from the side that faces the middle of the room, so the next mark never pins the diver to a wall.
                        float centre = (r.MinX + r.MaxX) * 0.5f;
                        target = ar.Body.Pos.X + (centre >= ar.Body.Pos.X ? 2.5f : -2.5f);
                    }
                    else if (ar.Engaged) target = feet.X;
                }
            }

            float move = System.MathF.Abs(target - feet.X) < 0.12f ? 0 : Mathx.Sign(target - feet.X);
            bool ripple = RippleComing(w);
            if (ripple) move = 0; // stand and jump it rather than run into it
            bool hop = climb || down || ripple;
            // Standing still, aim the swing at the nearest foe the way a mouse click would.
            float aim = 0f;
            if (move == 0 && attack)
                foreach (Enemy e in w.Foes)
                    if (e.Room == w.Room && e.Alive && System.MathF.Abs(e.Body.Pos.X - feet.X) < 3f) aim = e.Body.Pos.X - feet.X;
            return new PlayerInput
            {
                MoveX = move, Down = down, JumpPressed = hop && w.Player.Body.Grounded, JumpHeld = !down,
                AttackPressed = attack && !down, HasAim = aim != 0f, AimX = aim,
            };
        }
    }
}
